			logger.Fatalf("dial udp worker=%d: %v", i, err)
		}
		defer conn.Close()
		...
	}

const (
	defaultWorkers = 64
	maxWorkers     = 128
)

func (c *Config) normalize() {
	if c.Workers <= 0 {
		c.Workers = defaultWorkers
	}
	if c.Workers > maxWorkers {
		c.Workers = maxWorkers
	}
}

